export interface Frontmatter {
  title: string;
  date: string;
  tags: string[];
}

export interface Page {
  slug: string;
  frontmatter: Frontmatter;
  content: string;
  html: string;
}

import fs from 'fs';
import path from 'path';
import matter from 'gray-matter';
import { marked } from 'marked';
import { Page, Frontmatter } from './types';

const DEFAULT_FRONTMATTER: Frontmatter = {
  title: '',
  date: '',
  tags: [],
};

export function parseMarkdownFiles(contentDir: string): Page[] {
  const resolved = path.resolve(contentDir);
  const dirEntries = fs.readdirSync(resolved, { withFileTypes: true });

  const pages: Page[] = [];

  for (const entry of dirEntries) {
    if (!entry.isFile() || !entry.name.endsWith('.md')) continue;

    const filePath = path.join(resolved, entry.name);
    const raw = fs.readFileSync(filePath, 'utf-8');
    const { data, content } = matter(raw);

    const frontmatter: Frontmatter = {
      title: typeof data.title === 'string' ? data.title : DEFAULT_FRONTMATTER.title,
      date: typeof data.date === 'string' ? data.date : DEFAULT_FRONTMATTER.date,
      tags: Array.isArray(data.tags) ? data.tags : DEFAULT_FRONTMATTER.tags,
    };

    const html = marked.parse(content) as string;
    const slug = entry.name.replace(/\.md$/, '');

    pages.push({ slug, frontmatter, content, html });
  }

  pages.sort((a, b) => a.frontmatter.title.localeCompare(b.frontmatter.title));

  return pages;
}

import fs from 'fs';
import path from 'path';
import { Page } from './types';

function escapeHtml(text: string): string {
  return text
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function renderLayout(title: string, body: string): string {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${escapeHtml(title)}</title>
</head>
<body>
  ${body}
</body>
</html>`;
}

function renderPage(page: Page): string {
  const { title, date, tags } = page.frontmatter;
  const tagsHtml = tags.length
    ? `<p>Tags: ${escapeHtml(tags.join(', '))}</p>`
    : '';
  const dateHtml = date ? `<p>Date: ${escapeHtml(date)}</p>` : '';

  const body = `<h1>${escapeHtml(title)}</h1>
${dateHtml}
${tagsHtml}
${page.html}
<p><a href="index.html">Back to index</a></p>`;

  return renderLayout(title, body);
}

function renderIndex(pages: Page[]): string {
  const items = pages
    .map(
      (page) =>
        `<li><a href="${escapeHtml(page.slug)}.html">${escapeHtml(page.frontmatter.title)}</a></li>`
    )
    .join('\n');

  const body = `<h1>Site Index</h1>
<ul>
${items}
</ul>`;

  return renderLayout('Site Index', body);
}

export function generateSite(pages: Page[], outputDir: string): void {
  const resolved = path.resolve(outputDir);
  fs.mkdirSync(resolved, { recursive: true });

  for (const page of pages) {
    const html = renderPage(page);
    fs.writeFileSync(path.join(resolved, `${page.slug}.html`), html, 'utf-8');
  }

  const indexHtml = renderIndex(pages);
  fs.writeFileSync(path.join(resolved, 'index.html'), indexHtml, 'utf-8');
}

export { parseMarkdownFiles } from './parser';
export { generateSite } from './generator';
export { Page, Frontmatter } from './types';

#!/usr/bin/env node

import { parseMarkdownFiles, generateSite } from './index';

interface CliOptions {
  content: string;
  output: string;
}

function parseArgs(args: string[]): CliOptions {
  const options: CliOptions = { content: './content', output: './dist' };

  for (let i = 0; i < args.length; i++) {
    if (args[i] === '--content' && i + 1 < args.length) {
      options.content = args[i + 1];
      i++;
    } else if (args[i] === '--output' && i + 1 < args.length) {
      options.output = args[i + 1];
      i++;
    }
  }

  return options;
}

const args = process.argv.slice(2);

if (args[0] !== 'build') {
  console.error('Usage: ssg build [--content <dir>] [--output <dir>]');
  process.exit(1);
}

const options = parseArgs(args.slice(1));

const pages = parseMarkdownFiles(options.content);
generateSite(pages, options.output);

console.log(`Generated ${pages.length} page(s) in ${options.output}`);

