import fs from 'fs';
import path from 'path';
import os from 'os';
import { parseMarkdownFiles } from '../parser';

describe('parseMarkdownFiles', () => {
  let tmpDir: string;

  beforeEach(() => {
    tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-test-'));
  });

  afterEach(() => {
    fs.rmSync(tmpDir, { recursive: true, force: true });
  });

  function writeFile(name: string, content: string): void {
    fs.writeFileSync(path.join(tmpDir, name), content, 'utf-8');
  }

  it('returns an empty array for an empty directory', () => {
    const pages = parseMarkdownFiles(tmpDir);
    expect(pages).toEqual([]);
  });

  it('returns an empty array when directory has no .md files', () => {
    writeFile('notes.txt', 'hello');
    const pages = parseMarkdownFiles(tmpDir);
    expect(pages).toEqual([]);
  });

  it('parses a single markdown file with frontmatter', () => {
    writeFile('hello.md', `---
title: Hello World
date: 2024-01-01
tags:
  - js
  - ts
---
# Hello

This is a paragraph.`);

    const pages = parseMarkdownFiles(tmpDir);
    expect(pages).toHaveLength(1);
    expect(pages[0].slug).toBe('hello');
    expect(pages[0].frontmatter.title).toBe('Hello World');
    expect(pages[0].frontmatter.date).toBe('2024-01-01');
    expect(pages[0].frontmatter.tags).toEqual(['js', 'ts']);
    expect(pages[0].html).toContain('<h1');
    expect(pages[0].html).toContain('Hello');
    expect(pages[0].html).toContain('paragraph');
  });

  it('parses multiple markdown files', () => {
    writeFile('a.md', `---
title: Alpha
date: '2024-01-01'
tags: []
---
Alpha content`);

    writeFile('b.md', `---
title: Beta
date: '2024-02-01'
tags: []
---
Beta content`);

    const pages = parseMarkdownFiles(tmpDir);
    expect(pages).toHaveLength(2);
    // sorted by title
    expect(pages[0].frontmatter.title).toBe('Alpha');
    expect(pages[1].frontmatter.title).toBe('Beta');
  });

  it('handles missing frontmatter fields gracefully', () => {
    writeFile('minimal.md', `---
title: Just Title
---
No date or tags`);

    const pages = parseMarkdownFiles(tmpDir);
    expect(pages).toHaveLength(1);
    expect(pages[0].frontmatter.date).toBe('');
    expect(pages[0].frontmatter.tags).toEqual([]);
  });

  it('handles no frontmatter at all', () => {
    writeFile('plain.md', `# Just Content

Some text.`);

    const pages = parseMarkdownFiles(tmpDir);
    expect(pages).toHaveLength(1);
    expect(pages[0].frontmatter.title).toBe('');
    expect(pages[0].frontmatter.date).toBe('');
    expect(pages[0].frontmatter.tags).toEqual([]);
    expect(pages[0].html).toContain('<h1');
  });

  it('ignores non-markdown files', () => {
    writeFile('hello.md', `---
title: Hello
date: '2024-01-01'
tags: []
---
Hello`);

    writeFile('readme.txt', 'not markdown');
    writeFile('image.png', 'fake binary');

    const pages = parseMarkdownFiles(tmpDir);
    expect(pages).toHaveLength(1);
  });

  it('converts markdown to HTML correctly', () => {
    writeFile('formatting.md', `---
title: Format Test
date: '2024-01-01'
tags: []
---
# Heading

**Bold** and *italic*.

- List item 1
- List item 2

\`inline code\``);

    const pages = parseMarkdownFiles(tmpDir);
    expect(pages[0].html).toContain('<h1');
    expect(pages[0].html).toContain('<strong>Bold</strong>');
    expect(pages[0].html).toContain('<em>italic</em>');
    expect(pages[0].html).toContain('<li>List item 1</li>');
    expect(pages[0].html).toContain('<code>inline code</code>');
  });
});

import fs from 'fs';
import path from 'path';
import os from 'os';
import { Page } from '../types';
import { generateSite } from '../generator';

function makePage(overrides: Partial<Page> = {}): Page {
  return {
    slug: 'test-page',
    frontmatter: {
      title: 'Test Page',
      date: '2024-06-15',
      tags: ['typescript', 'testing'],
    },
    content: 'Some markdown content',
    html: '<p>Some markdown content</p>',
    ...overrides,
  };
}

describe('generateSite', () => {
  let tmpDir: string;

  beforeEach(() => {
    tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-gen-test-'));
  });

  afterEach(() => {
    fs.rmSync(tmpDir, { recursive: true, force: true });
  });

  it('creates the output directory if it does not exist', () => {
    const outDir = path.join(tmpDir, 'nested', 'output');
    generateSite([makePage()], outDir);
    expect(fs.existsSync(outDir)).toBe(true);
  });

  it('generates an index.html file', () => {
    generateSite([makePage()], tmpDir);

    const indexPath = path.join(tmpDir, 'index.html');
    expect(fs.existsSync(indexPath)).toBe(true);

    const html = fs.readFileSync(indexPath, 'utf-8');
    expect(html).toContain('<!DOCTYPE html>');
    expect(html).toContain('<title>Site Index</title>');
    expect(html).toContain('<h1>Site Index</h1>');
  });

  it('generates a page HTML file', () => {
    generateSite([makePage()], tmpDir);

    const pagePath = path.join(tmpDir, 'test-page.html');
    expect(fs.existsSync(pagePath)).toBe(true);

    const html = fs.readFileSync(pagePath, 'utf-8');
    expect(html).toContain('<!DOCTYPE html>');
    expect(html).toContain('<title>Test Page</title>');
    expect(html).toContain('<h1>Test Page</h1>');
    expect(html).toContain('<p>Some markdown content</p>');
  });

  it('includes date in page HTML when present', () => {
    generateSite([makePage({ frontmatter: { title: 'Dated', date: '2024-01-15', tags: [] } })], tmpDir);

    const html = fs.readFileSync(path.join(tmpDir, 'test-page.html'), 'utf-8');
    expect(html).toContain('Date: 2024-01-15');
  });

  it('omits date when empty', () => {
    generateSite([makePage({ frontmatter: { title: 'No Date', date: '', tags: [] } })], tmpDir);

    const html = fs.readFileSync(path.join(tmpDir, 'test-page.html'), 'utf-8');
    expect(html).not.toContain('Date:');
  });

  it('includes tags in page HTML when present', () => {
    generateSite([makePage()], tmpDir);

    const html = fs.readFileSync(path.join(tmpDir, 'test-page.html'), 'utf-8');
    expect(html).toContain('Tags: typescript, testing');
  });

  it('omits tags section when empty', () => {
    generateSite([makePage({ frontmatter: { title: 'No Tags', date: '', tags: [] } })], tmpDir);

    const html = fs.readFileSync(path.join(tmpDir, 'test-page.html'), 'utf-8');
    expect(html).not.toContain('Tags:');
  });

  it('index links to all pages', () => {
    const pages = [
      makePage({ slug: 'alpha', frontmatter: { title: 'Alpha', date: '', tags: [] } }),
      makePage({ slug: 'beta', frontmatter: { title: 'Beta', date: '', tags: [] } }),
    ];

    generateSite(pages, tmpDir);

    const html = fs.readFileSync(path.join(tmpDir, 'index.html'), 'utf-8');
    expect(html).toContain('<a href="alpha.html">Alpha</a>');
    expect(html).toContain('<a href="beta.html">Beta</a>');
  });

  it('pages link back to index', () => {
    generateSite([makePage()], tmpDir);

    const html = fs.readFileSync(path.join(tmpDir, 'test-page.html'), 'utf-8');
    expect(html).toContain('<a href="index.html">Back to index</a>');
  });

  it('generates valid HTML structure', () => {
    generateSite([makePage()], tmpDir);

    const html = fs.readFileSync(path.join(tmpDir, 'test-page.html'), 'utf-8');
    expect(html).toContain('<!DOCTYPE html>');
    expect(html).toContain('<html lang="en">');
    expect(html).toContain('<head>');
    expect(html).toContain('<meta charset="UTF-8">');
    expect(html).toContain('<body>');
  });

  it('escapes HTML in titles', () => {
    generateSite([makePage({ frontmatter: { title: 'A <script>alert("xss")</script>', date: '', tags: [] } })], tmpDir);

    const html = fs.readFileSync(path.join(tmpDir, 'test-page.html'), 'utf-8');
    expect(html).toContain('A &lt;script&gt;alert(&quot;xss&quot;)&lt;/script&gt;');
    expect(html).not.toContain('<script>alert');
  });

  it('generates multiple pages', () => {
    const pages = [
      makePage({ slug: 'page1', frontmatter: { title: 'Page 1', date: '', tags: [] } }),
      makePage({ slug: 'page2', frontmatter: { title: 'Page 2', date: '', tags: [] } }),
    ];

    generateSite(pages, tmpDir);
    expect(fs.existsSync(path.join(tmpDir, 'page1.html'))).toBe(true);
    expect(fs.existsSync(path.join(tmpDir, 'page2.html'))).toBe(true);
    expect(fs.existsSync(path.join(tmpDir, 'index.html'))).toBe(true);
  });
});

import { execSync } from 'child_process';
import fs from 'fs';
import path from 'path';
import os from 'os';

const CLI = path.resolve(__dirname, '../cli.ts');

function runCli(args: string): { stdout: string; stderr: string; status: number } {
  try {
    const stdout = execSync(`npx ts-node ${CLI} ${args}`, {
      encoding: 'utf-8',
      stdio: ['pipe', 'pipe', 'pipe'],
    });
    return { stdout, stderr: '', status: 0 };
  } catch (e: any) {
    return {
      stdout: e.stdout?.toString() || '',
      stderr: e.stderr?.toString() || '',
      status: e.status || 1,
    };
  }
}

function writeFile(dir: string, name: string, content: string): void {
  fs.writeFileSync(path.join(dir, name), content, 'utf-8');
}

describe('CLI', () => {
  let tmpDir: string;
  let contentDir: string;

  beforeEach(() => {
    tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'ssg-cli-test-'));
    contentDir = path.join(tmpDir, 'content');
    fs.mkdirSync(contentDir);
  });

  afterEach(() => {
    fs.rmSync(tmpDir, { recursive: true, force: true });
  });

  it('prints usage and exits with code 1 when no subcommand given', () => {
    const { stderr, status } = runCli('');
    expect(status).toBe(1);
    expect(stderr).toContain('Usage:');
  });

  it('generates site with default directories', () => {
    const defaultContent = path.resolve('./content');
    const defaultOutput = path.resolve('./dist');

    // Clean up in case they exist
    fs.rmSync(defaultContent, { recursive: true, force: true });
    fs.rmSync(defaultOutput, { recursive: true, force: true });

    fs.mkdirSync(defaultContent, { recursive: true });
    writeFile(defaultContent, 'hello.md', `---
title: Default Test
date: '2024-01-01'
tags: []
---
Default content.`);

    const { stdout, status } = runCli('build');
    expect(status).toBe(0);
    expect(stdout).toContain('Generated 1 page(s)');

    expect(fs.existsSync(path.join(defaultOutput, 'index.html'))).toBe(true);
    expect(fs.existsSync(path.join(defaultOutput, 'hello.html'))).toBe(true);

    // Cleanup
    fs.rmSync(defaultContent, { recursive: true, force: true });
    fs.rmSync(defaultOutput, { recursive: true, force: true });
  });

  it('respects --content and --output flags', () => {
    const customContent = path.join(tmpDir, 'mycontent');
    const customOutput = path.join(tmpDir, 'myoutput');
    fs.mkdirSync(customContent);

    writeFile(customContent, 'page.md', `---
title: Custom
date: '2024-01-01'
tags: []
---
Custom content.`);

    const { stdout, status } = runCli(`build --content ${customContent} --output ${customOutput}`);
    expect(status).toBe(0);
    expect(stdout).toContain('Generated 1 page(s)');
    expect(fs.existsSync(path.join(customOutput, 'page.html'))).toBe(true);
  });

  it('generates index with links to all pages', () => {
    writeFile(contentDir, 'a.md', `---
title: Page A
date: '2024-01-01'
tags: []
---
Content A`);

    writeFile(contentDir, 'b.md', `---
title: Page B
date: '2024-01-01'
tags: []
---
Content B`);

    const output = path.join(tmpDir, 'dist');

    const { status } = runCli(`build --content ${contentDir} --output ${output}`);
    expect(status).toBe(0);

    const indexHtml = fs.readFileSync(path.join(output, 'index.html'), 'utf-8');
    expect(indexHtml).toContain('<a href="a.html">Page A</a>');
    expect(indexHtml).toContain('<a href="b.html">Page B</a>');
  });

  it('handles empty content directory', () => {
    const output = path.join(tmpDir, 'dist');

    const { stdout, status } = runCli(`build --content ${contentDir} --output ${output}`);
    expect(status).toBe(0);
    expect(stdout).toContain('Generated 0 page(s)');
    expect(fs.existsSync(path.join(output, 'index.html'))).toBe(true);
  });
});

